describe('API Call Error Banner', () => {
  beforeEach(() => {
    cy.visit('/api-endpoint');
  });

  it('should display error banner when API call fails', () => {
    // Intercept the API call with a 500 Internal Server Error response
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('apiError');

    // Attempt to trigger the API call
    cy.get('[data-testid="fetch-data-button"]').click();

    // Wait for the error response
    cy.wait('@apiError');

    // Verify error banner is visible
    cy.get('[data-testid="error-banner"]').should('be.visible');
    cy.get('[data-testid="error-banner"]').should('contain', 'Error');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('contain', 'Internal Server Error');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify success button is disabled
    cy.get('[data-testid="success-button"]').should('be.disabled');

    // Verify error banner has a close button
    cy.get('[data-testid="close-error-button"]').should('be.visible');
  });

  it('should clear error banner when API call succeeds after failure', () => {
    // First, intercept with a failure
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('apiError');

    // Click the fetch button to trigger the error
    cy.get('[data-testid="fetch-data-button"]').click();

    // Wait for the error response
    cy.wait('@apiError');

    // Verify error banner is visible
    cy.get('[data-testid="error-banner"]').should('be.visible');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('contain', 'Internal Server Error');

    // Click the retry button
    cy.get('[data-testid="retry-button"]').click();

    // Intercept the API call with a successful response
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'Successful response' }
    }).as('apiSuccess');

    // Wait for the successful response
    cy.wait('@apiSuccess');

    // Verify error banner is no longer visible
    cy.get('[data-testid="error-banner"]').should('not.exist');

    // Verify success button is now enabled
    cy.get('[data-testid="success-button"]').should('be.visible');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('contain', 'Data fetched successfully');
  });
});
